mkuse!{use super :: abi :: usercalls ;}
mkuse!{use crate :: time :: Duration ;}
mkitem!{mkstruct!{# [derive (Copy , Clone , PartialEq , Eq , PartialOrd , Ord , Debug , Hash)] pub struct Instant (Duration) ;}}
mkitem!{mkstruct!{# [derive (Copy , Clone , PartialEq , Eq , PartialOrd , Ord , Debug , Hash)] pub struct SystemTime (Duration) ;}}
mkitem!{pub const UNIX_EPOCH : SystemTime = SystemTime (Duration :: from_secs (0)) ;}
mkitem!{mkimpl!{impl Instant { pub fn now () -> Instant { Instant (usercalls :: insecure_time ()) } pub fn checked_sub_instant (& self , other : & Instant) -> Option < Duration > { self . 0 . checked_sub (other . 0) } pub fn checked_add_duration (& self , other : & Duration) -> Option < Instant > { Some (Instant (self . 0 . checked_add (* other) ?)) } pub fn checked_sub_duration (& self , other : & Duration) -> Option < Instant > { Some (Instant (self . 0 . checked_sub (* other) ?)) } }}}
mkitem!{mkimpl!{impl SystemTime { pub fn now () -> SystemTime { SystemTime (usercalls :: insecure_time ()) } pub fn sub_time (& self , other : & SystemTime) -> Result < Duration , Duration > { self . 0 . checked_sub (other . 0) . ok_or_else (| | other . 0 - self . 0) } pub fn checked_add_duration (& self , other : & Duration) -> Option < SystemTime > { Some (SystemTime (self . 0 . checked_add (* other) ?)) } pub fn checked_sub_duration (& self , other : & Duration) -> Option < SystemTime > { Some (SystemTime (self . 0 . checked_sub (* other) ?)) } }}}